insert into todo.opuestos_levels (id, sort, title_es, title_en, clue_es, clue_en, words, layout) values ('hielo', 10, 'Hielo y agua', 'Ice and water', 'Un bloque de hielo corta el paso, y después hay agua.', 'A block of ice blocks the way, and then there''s water.', array['caliente', 'frio', 'mojado', 'seco']::text[], '{"objects":[{"id":"suelo_1","kind":"ground","pos":[-2.75,0.9],"size":[5.5,1.8]},{"id":"rampa","kind":"ramp","pos":[-4.341,2.481],"size":[2.64,0.3],"angle":-37.304,"target":false},{"id":"hielo","kind":"ice","noun":"el hielo","gender":"m","noun_en":"the ice","pos":[-1.2,2.6],"size":[0.8,1.6]},{"id":"piscina","kind":"ground","pos":[1.4,0.1],"size":[2.8,0.2]},{"id":"agua","kind":"water","noun":"el agua","gender":"f","noun_en":"the water","pos":[1.4,1],"zone":[0,0.2,2.8,1.8]},{"id":"suelo_2","kind":"ground","pos":[3,0.9],"size":[0.4,1.8]},{"id":"cesta_fondo","kind":"ground","pos":[4.05,0.7],"size":[1.7,0.6]},{"id":"cesta_pared","kind":"ground","pos":[5.05,1.5],"size":[0.3,2.2]},{"id":"pelota","kind":"ball","noun":"la pelota","gender":"f","noun_en":"the ball","pos":[-4.817,3.598],"size":[0.9,0.9],"held":true}],"goal":{"object":"pelota","zone":[3.2,0.9,4.9,2]},"solutions":[{"steps":[{"object":"hielo","word":"caliente"},{"object":"agua","word":"frio"}],"note":"Melt the ice, freeze the water."},{"steps":[{"object":"pelota","word":"caliente"},{"object":"agua","word":"frio"}],"note":"A hot ball melts the ice on its own."},{"steps":[{"object":"pelota","word":"frio"},{"object":"hielo","word":"caliente"}],"note":"A cold ball freezes the water as it lands."}]}'::jsonb)
